	WHERE
	    deleted_pro != 1
		and ",@statusIdFilter2,"
		and ",@statusIdFilter3,"
) projects
ORDER BY order_pst ASC, ",orderBy," ",orderType," LIMIT ",limitt," offset ",offsett,";
;");
PREPARE stmt FROM @queryy;
EXECUTE stmt;
